const contractClauses=$$('.clause');const signedClauses=new Set();contractClauses.forEach((clause,index)=>clause.addEventListener('click',()=>{clause.classList.toggle('signed');if(clause.classList.contains('signed'))signedClauses.add(index);else signedClauses.delete(index);if(signedClauses.size===contractClauses.length){$('#promise-reveal').classList.add('show');celebrate(55);setTimeout(()=>$('#promise-reveal').scrollIntoView({behavior:'smooth',block:'center'}),500)}}));
